set
  title = 'Music Theory I',
  goal = 'Music Theory I',
  summary = 'A first-semester college music theory course introducing the written, analytical, and practical foundations of tonal musicianship. Students study notation, rhythm and meter, scales, key signatures, intervals, triads, diatonic chords, elementary voice leading, cadences, and melodic analysis while connecting theory to listening, keyboard work, performance, and creative application.',
  data = $mt1json${"slug": "music-theory-i", "title": "Music Theory I", "description": "A first-semester college music theory course introducing the written, analytical, and practical foundations of tonal musicianship. Students study notation, rhythm and meter, scales, key signatures, intervals, triads, diatonic chords, elementary voice leading, cadences, and melodic analysis while connecting theory to listening, keyboard work, performance, and creative application.", "topics": [{"id": "a3d6a409-f4e4-40ca-b787-ce707892f738", "type": "topic", "title": "Staff, Clefs, and Notation", "description": "This opening unit gives students the notational fluency needed to read, write, analyze, and communicate musical ideas precisely.", "children": [{"id": "a0f1fadc-4cbf-4c6d-ad44-f2673fa929a5", "type": "subtopic", "title": "Pitch notation and the staff", "children": [{"id": "8e12166c-01ad-4658-8f03-5da62e5753b5", "type": "concept", "title": "staff lines and spaces"}, {"id": "a5db0a2e-213e-4dad-8789-47d226912bb3", "type": "concept", "title": "ledger lines"}, {"id": "906235cc-9d9e-427e-a803-538f42e8b785", "type": "concept", "title": "octave designation"}], "description": "Students learn how pitch is represented visually and how notation maps to sound and instruments."}, {"id": "c7bf66bc-f524-4754-93a9-160c3377068c", "type": "subtopic", "title": "Clefs and transposition awareness", "children": [{"id": "b72a4570-f071-43e1-b4ef-4b092a6a9321", "type": "concept", "title": "treble clef"}, {"id": "050b237e-d94a-441b-ac74-78f86c23940e", "type": "concept", "title": "bass clef"}, {"id": "513c53b4-64f9-42f7-9c3d-09945d3b5894", "type": "concept", "title": "C clefs"}], "description": "The class establishes treble, bass, alto, and tenor clef reading foundations."}, {"id": "7b39fdc7-35bc-4a73-af98-f60f36d0302c", "type": "subtopic", "title": "Notational conventions", "children": [{"id": "41dd5b64-4c15-4024-bf07-fc216f57c3af", "type": "concept", "title": "accidentals"}, {"id": "9f6dfd05-fac0-40bb-8421-624ecf9d1fde", "type": "concept", "title": "ties and slurs"}, {"id": "5c8119f5-789d-4713-9ad9-fbd150b0526e", "type": "concept", "title": "articulation and dynamics"}], "description": "Students learn the symbols and layout habits that make scores readable and professional."}]}, {"id": "c65181e1-6998-4ee1-9f73-d9f6d2627b75", "type": "topic", "title": "Rhythm and Meter", "description": "Rhythm and meter organize musical time; students learn to read, count, notate, and hear time structures accurately.", "children": [{"id": "a5866b9a-5a86-49a5-89b9-3c85834b3a2c", "type": "subtopic", "title": "Durations and rests", "children": [{"id": "052c9929-d12b-4e3b-83d0-4fc37313dbf4", "type": "concept", "title": "whole through sixteenth values"}, {"id": "e2c493e1-ab68-4ad8-b0a9-dc6bd80e9565", "type": "concept", "title": "dotted rhythms"}, {"id": "c972e37d-00fd-4549-9f1a-9ea8b4e56dd1", "type": "concept", "title": "ties"}], "description": "Students build confidence with note values, rests, dots, ties, and rhythmic grouping."}, {"id": "b64b0d2d-9330-4073-a879-1a5d1466e75e", "type": "subtopic", "title": "Simple and compound meter", "children": [{"id": "e8d4d106-6698-4724-9b0f-259a997c9580", "type": "concept", "title": "simple meter"}, {"id": "e298d5cd-9e92-47c1-967d-c7d64b9f9be1", "type": "concept", "title": "compound meter"}, {"id": "902e5dba-69ab-429b-a0a4-ffca11e609d0", "type": "concept", "title": "beat subdivision"}], "description": "The unit clarifies how beats divide and how meter shapes musical accent."}, {"id": "c9bf9aaf-cd70-4deb-8c64-a318ea2c9a13", "type": "subtopic", "title": "Syncopation and rhythmic fluency", "children": [{"id": "6d36a41c-2430-4cb5-b67a-192296c2a3af", "type": "concept", "title": "off-beat accents"}, {"id": "29f39e98-e9eb-42b5-a904-79c7b28483eb", "type": "concept", "title": "tuplets"}, {"id": "6a6a27b7-e6d9-48ed-9e9c-6434f8545943", "type": "concept", "title": "counting systems"}], "description": "Students practice rhythmic patterns that occur in classical, jazz, popular, and global repertoires."}]}, {"id": "183d20e1-3953-431a-a075-76cb3bd10b19", "type": "topic", "title": "Major and Minor Scales", "description": "Scales are the vocabulary of tonal music; this unit connects pattern, sound, notation, and function.", "children": [{"id": "9b7d8563-c5de-40b5-8eb4-06a173a667f4", "type": "subtopic", "title": "Major scale structure", "children": [{"id": "c3a5dacd-64d0-4d83-9ccb-519d300329d0", "type": "concept", "title": "whole/half pattern"}, {"id": "f32cf3df-615f-44b2-ac55-f25d8702e7b3", "type": "concept", "title": "scale degrees"}, {"id": "d73c2c20-0710-4ff2-8717-af345c5ce211", "type": "concept", "title": "tonic"}], "description": "Students learn the interval pattern that creates major keys and the sound of tonal stability."}, {"id": "ddab48f8-7c21-45d6-a533-97ff6fb4b07d", "type": "subtopic", "title": "Minor scale forms", "children": [{"id": "a0363be7-1736-46d6-9b46-5d2955570172", "type": "concept", "title": "natural minor"}, {"id": "597723eb-1814-4ead-baf8-6e4905f7b099", "type": "concept", "title": "harmonic minor"}, {"id": "e3fa948e-7998-474a-bb50-444c20317c49", "type": "concept", "title": "melodic minor"}], "description": "The class compares natural, harmonic, and melodic minor as practical tonal tools."}, {"id": "531d95ec-4280-466b-9683-4bb7eaf4f672", "type": "subtopic", "title": "Scale-degree function", "children": [{"id": "c51ee2fe-4436-4f7c-af6c-7a3b7d7c132b", "type": "concept", "title": "tonic"}, {"id": "0cb2f892-bc27-4d38-bfe9-88c3e36061c7", "type": "concept", "title": "dominant"}, {"id": "9d8b8ef1-0357-409f-a654-5b87530304ca", "type": "concept", "title": "leading tone"}], "description": "Students learn names and tendencies that later support melody, harmony, and analysis."}]}, {"id": "3214663e-6660-4ace-81ab-ed0f7feee51c", "type": "topic", "title": "Key Signatures", "description": "Key signatures help students read tonal music efficiently and understand relationships among keys.", "children": [{"id": "fcceb0bd-9d8b-4709-a984-a064052afeb7", "type": "subtopic", "title": "Circle of fifths", "children": [{"id": "b57488ec-b74d-4e1b-b789-833257baba94", "type": "concept", "title": "sharp keys"}, {"id": "e87ce77a-3093-4371-8669-ff5a33fa4d32", "type": "concept", "title": "flat keys"}, {"id": "289440f3-e0d4-41e2-b3f7-2e56eaa3f126", "type": "concept", "title": "enharmonic keys"}], "description": "Students learn the pattern connecting keys, accidentals, and closely related tonal areas."}, {"id": "68aa3bf5-19ec-4676-a8a5-a6c45a250902", "type": "subtopic", "title": "Major and relative minor keys", "children": [{"id": "1fd8b78c-34e7-442c-9d48-c6fa35c827b7", "type": "concept", "title": "relative minor"}, {"id": "3f465f81-f8bd-40bf-a89a-a188ab1fdcb4", "type": "concept", "title": "parallel minor"}, {"id": "0506266d-e87b-4ffc-9ace-c91728d4992b", "type": "concept", "title": "tonic identification"}], "description": "The unit links each key signature to major and minor tonal possibilities."}, {"id": "36e1639d-b182-4033-a9f9-f4ed2b4b254b", "type": "subtopic", "title": "Applied key fluency", "children": [{"id": "91843bd0-449c-49af-920e-b73319b38037", "type": "concept", "title": "key signature drills"}, {"id": "8a7d88cd-fc1a-49f2-ac7e-9845017e35a2", "type": "concept", "title": "scale writing"}, {"id": "4173f591-93ca-498c-a335-eab8dea7dd11", "type": "concept", "title": "aural/key recognition"}], "description": "Students practice identifying, writing, and using keys in short musical examples."}]}, {"id": "ee9ddb5f-340e-4e3d-936c-19ec02c8ad56", "type": "topic", "title": "Intervals", "description": "Intervals are the building blocks of melody and harmony; this unit develops precise identification, spelling, and listening.", "children": [{"id": "a53e310e-8762-412f-a70e-27305efaef2f", "type": "subtopic", "title": "Interval size and quality", "children": [{"id": "42c90a9e-da64-4349-9b24-3ddbd10d33f1", "type": "concept", "title": "perfect intervals"}, {"id": "d07d1333-2f26-43c3-8203-a6ab3c7e8aaa", "type": "concept", "title": "major/minor intervals"}, {"id": "66e9ba3c-8507-4a48-af77-9502b6f7af17", "type": "concept", "title": "augmented/diminished intervals"}], "description": "Students learn to label intervals accurately by number and quality."}, {"id": "b5ba7c5a-03fd-4a3a-809f-44131868dc4b", "type": "subtopic", "title": "Melodic and harmonic intervals", "children": [{"id": "55be39fd-b4df-49bd-9e38-41eb2323b71a", "type": "concept", "title": "ascending intervals"}, {"id": "0dfdf47f-51e0-4466-8c73-35afa4606258", "type": "concept", "title": "descending intervals"}, {"id": "1c509669-2c83-4aa2-8374-0aee88498745", "type": "concept", "title": "harmonic intervals"}], "description": "The class connects interval notation to both sequential and simultaneous sound."}, {"id": "32be0c9e-2c3c-4c26-af32-9e2e351f5fec", "type": "subtopic", "title": "Consonance, dissonance, and tendency", "children": [{"id": "187806f6-f917-4b7c-9db4-a21c3c149c73", "type": "concept", "title": "perfect consonance"}, {"id": "5aab01d3-b08e-4984-8ffe-ec40dcd6c4a2", "type": "concept", "title": "imperfect consonance"}, {"id": "8a25c73e-fb97-4da6-9323-0dc4de523e13", "type": "concept", "title": "dissonance"}], "description": "Students begin to hear why intervals feel stable, tense, or directional."}]}, {"id": "d609f33e-a975-4660-a422-30a962b045b5", "type": "topic", "title": "Triads and Chord Qualities", "description": "Triads introduce vertical harmony and prepare students for harmonic analysis, part-writing, and keyboard application.", "children": [{"id": "11039158-f33e-450c-b5cd-2566adeda3f3", "type": "subtopic", "title": "Building triads", "children": [{"id": "99fffe55-d28d-442f-8987-1add20c1dd0d", "type": "concept", "title": "root"}, {"id": "970e474b-43c9-440e-81e9-3473003e21f3", "type": "concept", "title": "third"}, {"id": "10f3161c-f01e-4b6c-a154-23e9155a6e2b", "type": "concept", "title": "fifth"}], "description": "Students learn to construct triads by stacking thirds from any root."}, {"id": "9babf9e8-b